// lib/theme.ts
import { createTheme } from '@mui/material/styles';

export const theme = createTheme({
  palette: {
    primary: { main: '#2563eb' },  // Blue
    secondary: { main: '#64748b' }, // Slate
    error: { main: '#ef4444' },    // Red (waste)
    warning: { main: '#f59e0b' },  // Amber (non-value-added)
    success: { main: '#10b981' },  // Green (value-added)
    info: { main: '#3b82f6' },     // Blue
  },
  typography: {
    fontFamily: [
      '-apple-system',
      'BlinkMacSystemFont',
      '"Segoe UI"',
      'Roboto',
      'sans-serif',
    ].join(','),
  },
  spacing: 4, // Base unit: 4px
});

// app/layout.tsx
import { ThemeProvider } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import { theme } from '@/lib/theme';

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body>
        <ThemeProvider theme={theme}>
          <CssBaseline />
          {children}
        </ThemeProvider>
      </body>
    </html>
  );
}

// components/ui/Button.tsx
import MuiButton from '@mui/material/Button';

export function Button({ variant = 'contained', ...props }) {
  return <MuiButton variant={variant} {...props} />;
}

// Variants: 'contained' (primary), 'outlined' (secondary), 'text' (tertiary)
// Color prop for destructive: color="error"
